// Порівняння документ до документа. Ніякої моделі: це арифметика й теорія множин.
const meta = $('Пари клієнт — контрагент').first().json;
let ourBalance = 0;
try {
  const bal = $('BAS — сальдо взаєморозрахунків').first().json;
  ourBalance = Number((bal.value ?? [])[0]?.СуммаBalance ?? 0);
} catch (e) { ourBalance = 0; }

const ours = $input.all().map(i => i.json);
ourBalance = ourBalance || Number(ours.reduce((a, d) => a + Number(d.amount_total || 0), 0).toFixed(2));

// Перелік контрагента приходить пізніше — коли він підпише або надішле свій акт.
// На цьому кроці фіксуємо своє й позначаємо розбіжності всередині власних даних.
const discrepancies = [];
for (const d of ours) {
  if (d.status === 'error') discrepancies.push({ side: 'us', doc: d.doc_type + ' № ' + d.doc_number, amount: Number(d.amount_total), note: 'Документ не проведено — помилка обробки' });
  if (d.status === 'review') discrepancies.push({ side: 'us', doc: d.doc_type + ' № ' + d.doc_number, amount: Number(d.amount_total), note: 'Документ ще на перевірці, у сальдо не врахований' });
}

return [{ json: {
  client_id: meta.client_id,
  counterparty_id: meta.cp_id,
  cp_name: meta.cp_name,
  cp_email: meta.email_docs,
  period_from: meta.period_from,
  period_to: meta.period_to,
  our_balance: ourBalance,
  documents: ours,
  discrepancies,
  status: discrepancies.length ? 'disputed' : 'draft'
}}];
